/// <summary>
/// MPJ_28395_Stock reservation - Auto reservation helper class
/// </summary>
 
class METSalesOrderAutoReserve
{
}

Method.Source:
    /// <summary>
    /// check substitute
    /// </summary>
    /// <param name = "_salesLine">_salesLine</param>
    /// <param name = "_metSalesLine">_metSalesLine</param>
    /// <param name = "_inventDim">_inventDim</param>
    /// <returns>Sales line</returns>
    public SalesLine applySubstitution(SalesLine       _salesLine,
                                       METSalesLine    _metSalesLine,
                                       InventDim       _inventDim)
    {
        METSalesItemSubstitution_AutoReserve    metSalesItemSubstitution_AutoReserve = METSalesItemSubstitution_AutoReserve::ConstructAutoReserve(_salesLine,
                                                                                                                                                  _metSalesLine,
                                                                                                                                                  _inventDim);
        METSalesItemSubstitute  itemSub;
        SalesLine               salesLine;

        if (metSalesItemSubstitution_AutoReserve.validate())
        {
            InventQty           inventQty;
            InventTrans         inventTrans;
            InventTransOrigin   inventTransOrigin;
           
            select sum(Qty) from inventTrans
                exists join inventTransOrigin
                    where inventTrans.InventTransOrigin == inventTransOrigin.RecId &&
                          inventTransOrigin.InventTransId == _salesLine.InventTransId &&
                          inventTrans.StatusReceipt == StatusReceipt::None &&
                          inventTrans.StatusIssue   == StatusIssue::OnOrder;

            inventQty = - inventTrans.Qty;

            if (inventQty == _salesLine.QtyOrdered)
            {
                Qty         qtyOnHand                   = metSalesItemSubstitution_AutoReserve.queryOnHandQty(_salesLine.ItemId, _inventDim);

                if(qtyOnHand < _salesLine.QtyOrdered)
                {
                    itemSub = metSalesItemSubstitution_AutoReserve.searchSubstitionItem();

                    if (itemSub)
                    {
                        salesLine   = metSalesItemSubstitution_AutoReserve.createSalesLine(itemSub);
                    }
                }
            }
           
        }

        return (salesLine.RecId && (_salesLine.RecId != salesLine.RecId)) ? salesLine : null;
    }
